4: 
5: /* This file defines the colors used for the main layout of the application.
6:  * Colors that define a containers for content or their text color should go
7:  *  here. Colors that define widgets or content should not */
8: 
9: /* Background 0 should be used for the main content or page background */
10: /* Background 1 should be used for center panes and secondary sidebars */
11: /* Background 2 should be used for primary sidebars */
12: /* Background 3 should be used for blocks of content inside the main content */
13: /* Background 4 should be used for elements inside the main content */
14: 
15: /* Color 0 should be used when the text needs more emphasis */
16: /* Color 1 should be used for the main text color */
17: /* Color 2 should be used when the text needs less emphasis */
18: /* Color 3 should be used when the text need even less emphasis */
19: 
20: /* Border 0 should be used for separation from main layout sections */
21: /* Border 1 should be used when the separation is part of the element */
22: 
23: :host,
24: :root {
25:   --layout-background-0: light-dark(var(--color-white), var(--color-gray-90));
26:   --layout-background-1: light-dark(var(--color-gray-05), var(--color-gray-80));
27:   --layout-background-2: light-dark(var(--color-gray-10), var(--color-gray-70));
28:   --layout-background-3: light-dark(var(--color-gray-20), var(--color-gray-60));
29:   --layout-background-4: light-dark(var(--color-gray-30), var(--color-gray-50));
30: 
31:   --layout-color-0: light-dark(var(--color-black), var(--color-white));
32:   --layout-color-1: light-dark(var(--color-gray-90), var(--color-gray-10));
33:   --layout-color-2: light-dark(var(--color-gray-70), var(--color-gray-30));
34:   --layout-color-3: var(--color-gray-50);
35: 
36:   --layout-border-0: var(--color-neutral-200);
37:   --layout-border-1: light-dark(var(--color-gray-40), var(--color-gray-60));
38:   --layout-border-2: var(--color-gray-50);
39: 
40:   @media (prefers-contrast) {
41:     --layout-background-0: Window;
42:     --layout-background-1: -moz-Dialog;
43:     --layout-background-2: transparent;
44:     --layout-background-3: transparent;
45:     --layout-background-4: transparent;
46: 
47:     --layout-color-0: WindowText;
48:     --layout-color-1: -moz-DialogText;
49:     --layout-color-2: currentColor;
50:     --layout-color-3: currentColor;
51: 
52:     --layout-border-0: ThreeDShadow;
53:     --layout-border-1: ThreeDShadow;
54:     --layout-border-2: ThreeDShadow;
55:   }
56: }
